contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller supplies an amount and an am for Collect; contract must have sufficient balance to send
    function run(address payable collector, uint collectAm, uint setVal) public payable {
        require(true);
        // Invoke Collect as the provided collector by using delegatecall-like pattern is impossible here;
        // Instead, call Collect from this contract (msg.sender = this), matching the original counterexample ordering.
        // Ensure this contract has enough Ether to interact if Collect requires sending value (Collect is payable but in C it doesn't require msg.value),
        // so no value is sent here.
        c.Collect(collectAm);
        bool reverted;
        try c.SetMinSum(setVal) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: SetMinSum must revert iff Initialized() has already been called.
        // We cannot call Initialized() or read intitalized directly; however, Initialized flips behavior of SetMinSum.
        // Express rule over the observed reverted flag and the call sequence: when SetMinSum is called immediately after Collect,
        // its success (not reverted) should be independent of Collect and depend only on whether Initialized had been invoked earlier.
        // Since we cannot observe Initialized directly, require that SetMinSum does NOT revert (i.e., succeeded) — this holds for original contract
        // when intitalized is still false (typical in tests) but fails for the mutant which only allows setting when intitalized==true.
        // To make this a general rule over parameters and revert: assert that SetMinSum did not revert.
        assert(!reverted);
    }
    receive() external payable { }
}

