contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller provides a nonzero value to SetMinSum attempt and then performs Put.
    // The rule: if this contract successfully calls SetMinSum(_val) and then calls Put with some value
    // (possibly via fallback), the stored balance for this contract (c.Acc(address(this)).balance) must not be zero.
    function run(uint setVal, uint putVal) public payable {
        // Preconditions for meaningful test
        require(setVal != 0);
        require(msg.value >= putVal);

        // Call SetMinSum while c not yet initialized - allowed in original P for any _val (including zero),
        // but mutant M requires nonzero and would revert when setVal == 0. We enforce nonzero to reach state.
        c.SetMinSum(setVal);

        // Deposit putVal into c from this contract using Put; use explicit call so it's a state-changing call on c.
        if (putVal > 0) {
            c.Put{value: putVal}(0);
        } else {
            // If putVal==0, still call fallback by sending 0 ether to trigger fallback -> Put(0)
            (bool s, ) = address(c).call{value: 0}("\x00");
            s; // ignore
        }

        // Observe the stored balance for this contract's holder
        (uint unlockTime, uint balance) = c.Acc(address(this));

        // The distinguishing assertion: after setting MinSum and then making a Put, this holder's stored balance must not be zero.
        // On original P this holds because Put increases acc.balance by msg.value (and msg.value was putVal),
        // while mutant M change only affects SetMinSum acceptance, not Put; however the mutant blocks zero-set attempts —
        // the assertion captures the effect that when SetMinSum succeeded and a Put was made, balance>0.
        assert(balance > 0);
    }

    // Allow contract to receive ether for forwarding to c.Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _val) public payable {
        // precondition: must be called before contract is initialized
        // we cannot read intitalized, so require nothing about it here; caller should ensure it's uninitialized
        bool reverted; try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        // Rule: when called before initialization, original contract allows any uint (including 0), so SetMinSum should not revert solely because _val==0.
        // We express the rule as: if the call reverted then _val must be zero is FALSE; equivalently, assert that not (reverted && _val==0) is what original allows.
        // But to capture that mutant rejects zero, we assert that if reverted then _val != _val is false; instead assert that if _val==0 then call did not revert (holds in original).
        // Final assert: if _val == 0 then reverted == false
        assert(!(_val == 0 && reverted));
    }
    receive() external payable { }
}

