    // We also fuzz an address but deploy a helper Reverter and pass its address to SetLogFile.
    function testFuzz_property(uint256 newMin, bool doInit) public {
        // Keep domain wide; bound newMin into full uint range (no tight restriction)
        uint256 val = newMin; // allow full range

        // Deploy adversarial log that will revert when AddMessage is called
        Reverter rev = new Reverter();

        // Set the log file to the adversarial contract
        c.SetLogFile(address(rev));

        // Optionally initialize the contract
        if (doInit) {
            c.Initialized();
        }

        // Call SetMinSum and observe whether it succeeded (did not revert)
        bool ok;
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C satisfies: if the call reverted due to initialized guard, MinSum remains as before (defaults 0 or prior set);
        // In particular, when doInit==true the call must revert and leave MinSum unchanged (so ok==false and c.MinSum() != val).
        // The mutant may set MinSum before revert causing c.MinSum()==val even though call should not have succeeded.
        // We assert the general rule that after the call either it succeeded and MinSum==val, or it reverted and MinSum!=val when contract was initialized.
        // This single assertion is true for the reference for all inputs and false for the mutant for some inputs.
        if (doInit) {
            // If initialized, the correct contract must revert the SetMinSum call; thus ok must be false and MinSum must not equal val.
            assertTrue(!ok && c.MinSum() != val);
